```python
import os
import sys
import csv
import json
import time
from datetime import datetime, timedelta
import matplotlib.pyplot as plt
import numpy as np
from concurrent.futures import ThreadPoolExecutor, as_completed
import requests
import re

class Config:
    DATA_DIR = "data"
    DB_HOST = "localhost"
    DB_NAME = "analyticDB"
    DB_USER = "admin"
    DB_PASS = "password"
    FILE_EXTENSIONS = ["csv", "json"]
    MAX_THREADS = 20
    REPORT_DIR = "reports"

class Logger:
    def __init__(self):
        self.logger = logging.getLogger(__name__)

    def info(self, msg):
        self.logger.info(msg)

    def error(self, msg):
        self.logger.error(msg)

logger = Logger()

def main():
    db_connector = DatabaseConnector(host=Config.DB_HOST,
                                     database=Config.DB_NAME,
                                     user=Config.DB_USER,
                                     password=Config.DB_PASS)

    params = {
        'data_dir': Config.DATA_DIR,
        'extensions': Config.FILE_EXTENSIONS
    }

    start_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    logger.info(f"数据分析程序启动，时间：{start_time}")

    files = []
    for root, dirs, filenames in os.walk(Config.DATA_DIR):
        for file in filenames:
            if file.lower().endswith(('.csv', '.json')):
                files.append(os.path.join(root, file))

    results = {}

    executor = ThreadPoolExecutor(max_workers=Config.MAX_THREADS)
    futures = []
    progress = 0

    for file in files:
        file_name = os.path.basename(file)
        future = executor.submit(process_file, file, db_connector, results)
        futures.append(future)

    total_files = len(files)
    for future in as_completed(futures):
        result = future.result()
        if isinstance(result, dict) and 'progress' in result:
            progress += result['progress']
            logger.info(f"完成文件：{file_name}, 进度：{result['progress']}%")

    logger.info(f"全部处理完成，总进度：{progress}%")

if __name__ == "__main__":
    main()

class DatabaseConnector:
    def __init__(self, host, database, user, password):
        self.conn = None
        self._connect()

    def _connect(self):
        try:
            if self.conn is None:
                self.conn = psycopg2.connect(
                    host=self.host,
                    database=self.database,
                    user=self.user,
                    password=self.password
                )
        except Exception as e:
            logger.error(f"数据库连接失败：{str(e)}")

    def close(self):
        if self.conn:
            self.conn.close()

    def execute(self, query, params=None):
        try:
            cursor = self.conn.cursor()
            if params:
                cursor.execute(query, params)
            else:
                cursor.execute(query)
            self.conn.commit()
            return True
        except Exception as e:
            logger.error(f"数据库执行失败：{str(e)}")
            return False

def process_file(file_path, db_connector, results):
    try:
        file_name = os.path.basename(file_path)

        progress = 0
        total_progress = 100

        with open(file_path, 'rb') as f:
            chunk_size = 2 * 1024 ** 2  # 2MB per chunk
            for chunk in iter(lambda: f.read(chunk_size), b''):
                if len(chunk) < chunk_size:
                    break

                progress += chunk_size / os.path.getsize(file_path) * total_progress
                logger.info(f"处理文件：{file_name}，已完成进度：{progress:.2f}%")

                try:
                    if file_path.lower().endswith('.csv'):
                        data = csv.reader(chunk.decode('utf-8'))
                    else:
                        data = json.load(chunk)

                    cleaned_data = clean_data(data)
                    results[file_name] = cleaned_data

                    logger.info(f"文件：{file_name} 清洗完成，存储到结果中。")
                except Exception as e:
                    logger.error(f"处理文件：{file_name} 错误，原因：{str(e)}")
                    return {'error': str(e)}

        return {'progress': progress}
    except Exception as e:
        logger.error(f"文件处理失败：{str(e)}")
        return {'error': str(e)}

def clean_data(data):
    try:
        # 去重
        if isinstance(data, list):
            unique_data = []
            seen = set()
            for item in data:
                key = tuple(item.keys()) if isinstance(item, dict) else (item[0],)
                if key not in seen:
                    seen.add(key)
                    unique_data.append(item)
            data = unique_data

        # 缺失值处理
        if isinstance(data, list):
            for i in range(len(data)):
                if any(isinstance(data[i][k], str) and data[i][k] == '' for k in data[0].keys()):
                    default_values = get_default_values()
                    for key, value in zip(data[0].keys(), default_values):
                        if isinstance(data[i], dict):
                            data[i][key] = value
                        else:
                            # 不支持，无法处理为字典形式
                            pass

        # 时间格式统一
        if isinstance(data, list):
            for i in range(len(data)):
                date_field = get_date_field()
                if date_field and isinstance(data[i], dict) and data[i].get(date_field):
                    date = datetime.strptime(data[i][date_field], "%Y-%m-%d")
                    data[i][date_field] = date.strftime("%Y-%m-%d %H:%M:%S")

        # 文本标准化
        if isinstance(data, list):
            for i in range(len(data)):
                text_fields = get_text_fields()
                for field in text_fields:
                    if isinstance(data[i], dict) and data[i].get(field):
                        text = data[i][field]
                        cleaned_text = clean_text(text)
                        data[i][field] = cleaned_text

        return data
    except Exception as e:
        logger.error(f"数据清洗失败，原因：{str(e)}")
        return None

def clean_text(text):
    try:
        # 去除特殊符号和分词
        text = re.sub(r'[^\w\s-]', '', text)
        tokens = text.split()
        return ' '.join(tokens)
    except Exception as e:
        logger.error(f"文本清洗失败，原因：{str(e)}")
        return text

class DefaultValuesConfig:
    def __init__(self):
        self.default_values = {
            'age': 0,
            'score': 0.0,
            'status': 'active',
            'create_date': datetime.now().strftime("%Y-%m-%d"),
            'update_date': None
        }

def get_default_values():
    return DefaultValuesConfig().default_values

class DateFieldConfig:
    def __init__(self):
        self.date_field = "transaction_date"

def get_date_field():
    return DateFieldConfig().date_field

class TextFieldConfig:
    def __init__(self):
        self.text_fields = ["comments", "description"]

def get_text_fields():
    return TextFieldConfig().text_fields
```

### 代码说明

1. **清洗流程**：
   - **去重**：使用字典或元组作为键来保证唯一性。
   - **缺失值处理**：根据配置文件提供默认值，填充空白数据。
   - **时间格式统一**：将日期格式转换为标准形式。
   - **文本标准化**：去除特殊符号并进行分词。

