```cpp
#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <algorithm>
#include <regex>
#include <ctime>
#include <fstream>
#include <iterator>
#include <numeric>
#include <cmath>
#include <boost/thread.hpp>

using namespace std;

// 配置参数类（在C++中使用枚举和常数）
class Config {
public:
    static const string DATA_DIR = "data";
    static const string DB_HOST = "localhost";
    static const string DB_NAME = "analyticDB";
    static const string DB_USER = "admin";
    static const string DB_PASS = "password";
    static const vector<string> FILE_EXTENSIONS = {"csv", "json"};
    static const int MAX_THREADS = 20;
    static const string REPORT_DIR = "reports";
};

// 日志记录类
class Logger {
private:
    static Logger* instance;
    mutex lock;

public:
    Logger() {}
    ~Logger() {}

    void info(const string& msg) {
        lock_guard g(lock);
        cout << "[INFO] " << msg << endl;
    }

    void error(const string& msg) {
        lock_guard g(lock);
        cout << "[ERROR] " << msg << endl;
    }

    static Logger* getInstance() {
        if (instance == nullptr) {
            instance = new Logger();
        }
        return instance;
    }
};

Logger& logger = Logger::getInstance();

// 数据库连接类
class DatabaseConnector {
private:
    string host, database, user, pass;
    shared_ptr<sqlite3::sqlite3> conn;

public:
    DatabaseConnector(const string& h, const string& db, const string& u, const string& p)
        : host(h), database(db), user(u), pass(p) {
        conn = make_shared<sqlite3::sqlite3>();
        connect();
    }

    void connect() {
        try {
            if (conn == nullptr) {
                sqlite3::sqlite3* tmp_conn = new sqlite3::sqlite3;
                bool success = tmp_conn->open(host, database, user.c_str(), pass.c_str());
                if (!success) throw "数据库连接失败";
                conn = make_shared<sqlite3::sqlite3>(tmp_conn);
            }
        } catch (const string& e) {
            logger.error(e);
        }
    }

    ~DatabaseConnector() {
        if (conn) {
            conn->close();
        }
    }

    bool execute(const string& query, const vector<string>& params = {}) {
        try {
            sqlite3::sqlite3* db = conn.get();
            sqlite3::stmt* stmt = db->prepare(query.c_str());

            for (size_t i = 0; i < params.size(); ++i) {
                bind_param(stmt, i + 1, params[i].c_str());
            }

            int success = 0;
            if (!stmt->step() && !stmt->reset()) {
                logger.error("数据库执行失败");
                return false;
            }
            success = stmt->done();
            delete_stmt(stmt);

            conn->commit();
            return true;
        } catch (const string& e) {
            logger.error(e);
            return false;
        }
    }
};

// 清洗和预处理函数
class DataCleaner {
private:
    vector<string> text_fields;
    string date_field;

public:
    DataCleaner(const vector<string>& tf, const string& df)
        : text_fields(tf), date_field(df) {}

    map<string, string> clean(const map<string, variant<string, vector<string>>>>& data) {
        map<string, string> cleaned;

        // 去重
        if (data.size() > 0 && is_list(data[0])) {
            vector<tuple<string, size_t>> unique;
            set<tuple<string, size_t>> seen;

            for (size_t i = 0; i < data.size(); ++i) {
                tuple keys = make_tuple(data[i].begin(), data[i].end());
                if (seen.find(keys) == seen.end()) {
                    seen.insert(keys);
                    unique.push_back(keys);
                }
            }

            vector<map<string, string>> unique_data;
            for (const auto& u : unique) {
                map<string, string> item;
                for (size_t j = 0; j < data.size(); ++j) {
                    if (u.mbegin() == data[j].begin()) {
                        copy(data[j].cbegin(), data[j].cend(), inserter(item, item.begin()));
                        break;
                    }
                }
                unique_data.push_back(item);
            }

            for (size_t i = 0; i < unique.size(); ++i) {
                map<string, string>& md = unique_data[i];
                for (const auto& kv : md) {
                    cleaned[kv.first] = kv.second;
                }
            }
        } else {
            // 处理单条记录
            for (auto& item : data) {
                cleaned[get<0>(item.keys())] = item[get<1>(item.keys())];
            }
        }

        return cleaned;
    }

    string cleanText(const string& text) {
        try {
            regex pattern(R"([^\w\s-])");
            string result = regex_replace(text, R"", $1);

            vector<string> tokens;
            size_t start = 0;

            while (start < result.size()) {
                size_t end = result.find(' ', start);
                if (end == string::npos) {
                    tokens.push_back(result.substr(start));
                    break;
                }
                tokens.push_back(result.substr(start, end - start));
                start = end + 1;
            }

            return join(tokens, " ");
        } catch (const regex_base_error& e) {
            logger.error("文本清洗失败，正则表达式错误");
            return text;
        }
    }

    map<string, string> fillMissingValues(const vector<map<string, string>>& data,
                                         const vector<string>& defaults) {
        for (auto& item : data) {
            for (const auto& kv : item) {
                if (string().compare(kv.second) == 0) {
                    for (size_t i = 0; i < defaults.size(); ++i) {
                        if (!item.count(defaults[i])) {
                            item[defaults[i]] = get<1>(defaults[i]);
                        }
                    }
                }
            }
        }

        return data;
    }

    map<string, string> normalizeDate(map<string, string>& data) {
        if (date_field.empty()) return data;

        const string format = "%Y-%m-%d";
        for (auto& item : data) {
            if (item.find(date_field) != item.end()) {
                string date_str = item[date_field];
                try {
                    time_t now;
                    tm* pt = localtime(&now);

                    struct tm parse_tm = {};
                    memset(&parse_tm, 0, sizeof(struct tm));
                    if (strptime(date_str.c_str(), format.c_str(), &parse_tm)) {
                        mktime(&parse_tm);
                        char buffer[20];
                        snprintf(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", parse_tm.tm_year + 1900,
                                 parse_tm.tm_mon + 1, parse_tm.tm_mday, parse_tm.tm_hour, parse_tm.tm_min, parse_tm.tm_sec);
                        item[date_field] = string(buffer);
                    } else {
                        logger.error("无法解析日期格式");
                        return data;
                    }
                } catch (...) {
                    logger.error("日期解析失败");
                    return data;
                }
            }
        }

        return data;
    }
};

// 处理函数
vector<map<string, string>> processFile(const string& file_path, DatabaseConnector* db_connector,
                                      vector<map<string, string>>& results) {
    try {
        vector<map<string, string>> data;

        // 读取文件内容
        ifstream fin(file_path);
        string line;
        while (getline(fin, line)) {
            map<string, string> item;
            // 解析JSON或CSV格式的数据（示例仅展示解析逻辑）
            if (line[0] != '#' && !line.empty()) {
                size_t pos = line.find(':');
                if (pos != string::npos) {
                    string key = line.substr(0, pos);
                    string value = line.substr(pos + 1);
                    item[key] = value;
                } else {
                    // 处理CSV格式
                    vector<string> fields;
                    size_t comma_pos = line.find(',');
                    while (comma_pos != string::npos) {
                        fields.push_back(line.substr(0, comma_pos));
                        if (comma_pos == line.size() - 1) break;
                        comma_pos += line.find(',', comma_pos + 1);
                    }
                    for (size_t i = 0; i < fields.size(); ++i) {
                        item[to_string(i)] = fields[i];
                    }
                }
            }

            data.push_back(item);
        }

        // 数据清洗
        DataCleaner cleaner({ "comments", "description" }, "transaction_date");
        vector<map<string, string>> cleaned_data = cleaner.clean(data);

        // 存储到数据库
        for (auto& item : cleaned_data) {
            if (!db_connector->execute("INSERT INTO cleaned_data (key, value) VALUES (?, ?)",
                                       {item[0].c_str(), item[1].c_str()})) {
                logger.error("数据存储失败");
            }
        }

        results.push_back(cleaned_data);
        return results;
    } catch (const exception& e) {
        logger.error(e.what());
        return results;
    }
}

// 主函数
int main() {
    vector<map<string, string>> results;

    // 初始化数据库连接
    DatabaseConnector db_connector(
        Config::DB_HOST, Config::DB_NAME, Config::DB_USER, Config::DB_PASS);

    if (db_connector.execute("CREATE TABLE IF NOT EXISTS cleaned_data (id INTEGER PRIMARY KEY AUTOINCREMENT, key TEXT, value TEXT)")) {
        logger.info("创建新表成功");
    } else {
        logger.error("无法创建数据库表");
        return -1;
    }

    // 处理文件
    vector<string> files = { "chat_data.csv", "transaction_data.json" };

    for (const string& file : files) {
        try {
            processFile(file, &db_connector, results);
        } catch (const exception& e) {
            logger.error(e.what());
        }
    }

    return 0;
}
```

