#### **5. 数据清洗器**

```cpp
class DataCleaner {
private:
    vector<string> text_fields;
    string date_field;

public:
    DataCleaner(const vector<string>& tf, const string& df)
        : text_fields(tf), date_field(df) {}

    map<string, string> clean(const map<string, variant<string, vector<string>>>>& data) {
        map<string, string> cleaned;

        // 去重
        if (data.size() > 0 && is_list(data[0])) {
            vector<tuple<string, size_t>> unique;
            set<tuple<string, size_t>> seen;

            for (size_t i = 0; i < data.size(); ++i) {
                tuple keys = make_tuple(data[i].begin(), data[i].end());
                if (seen.find(keys) == seen.end()) {
                    seen.insert(keys);
                    unique.push_back(keys);
                }
            }

            vector<map<string, string>> unique_data;
            for (const auto& u : unique) {
                map<string, string> item;
                for (size_t j = 0; j < data.size(); ++j) {
                    if (u.mbegin() == data[j].cbegin()) {
                        copy(data[j].cbegin(), data[j].cend(), inserter(item, item.begin()));
                        break;
                    }
                }
                unique_data.push_back(item);
            }

            for (size_t i = 0; i < unique.size(); ++i) {
                const auto& md = unique_data[i];
                for (const auto& kv : md) {
                    cleaned[kv.first] = kv.second;
                }
            }
        } else {
            // 处理单条记录
            for (auto& item : data) {
                cleaned[get<0>(item.keys())] = item[get<1>(item.keys())];
            }
        }

        return cleaned;
    }

    string cleanText(const string& text) {
        try {
            regex pattern(R"([^\w\s-])");
            string result = regex_replace(text, R"", $1);

            vector<string> tokens;
            size_t start = 0;

            while (start < result.size()) {
                size_t end = result.find(' ', start);
                if (end == string::npos) {
                    tokens.push_back(result.substr(start));
                    break;
                }
                tokens.push_back(result.substr(start, end - start));
                start = end + 1;
            }

            return join(tokens, " ");
        } catch (const regex_base_error& e) {
            logger.error("文本清洗失败，正则表达式错误");
            return text;
        }
    }

    map<string, string> fillMissingValues(const vector<map<string, string>>& data,
                                         const vector<string>& defaults) {
        for (auto& item : data) {
            for (const auto& kv : item) {
                if (string().compare(kv.second) == 0) {
                    for (size_t i = 0; i < defaults.size(); ++i) {
                        if (!item.count(defaults[i])) {
                            item[defaults[i]] = get<1>(defaults[i]);
                        }
                    }
                }
            }
        }

        return data;
    }

    map<string, string> normalizeDate(map<string, string>& data) {
        if (date_field.empty()) return data;

        const string format = "%Y-%m-%d";
        for (auto& item : data) {
            if (item.find(date_field) != item.end()) {
                string date_str = item[date_field];
                try {
                    time_t now;
                    tm* pt = localtime(&now);

                    struct tm parse_tm = {};
                    memset(&parse_tm, 0, sizeof(struct tm));
                    if (strptime(date_str.c_str(), format.c_str(), &parse_tm)) {
                        mktime(&parse_tm);
                        char buffer[20];
                        snprintf(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", parse_tm.tm_year + 1900,
                                 parse_tm.tm_mon + 1, parse_tm.tm_mday, parse_tm.tm_hour, parse_tm.tm_min, parse_tm.tm_sec);
                        item[date_field] = string(buffer);
                    } else {
                        logger.error("无法解析日期格式");
                        return data;
                    }
                } catch (...) {
                    logger.error("日期解析失败");
                    return data;
                }
            }
        }

        return data;
    }
};
```

**注释：**
- **`DataCleaner`类**：负责对数据进行清洗和预处理，支持去重、缺失值填充、日期格式转换和文本标准化等功能。
- **成员函数说明**：
  - `clean(const map<string, variant<string, vector<string>>>>& data)`：主要清洗方法。
    - 判断是否需要去重，通过`set<tuple>`保证唯一性。
    - 填充缺失值，使用默认值配置文件中的值。
    - 格式化日期，将日期字符串转换为标准格式。
  - `cleanText(const string& text)`：对文本进行清洗，去除非字母数字符号。
  - `fillMissingValues(...)`：填充缺失值，根据默认值配置文件进行操作。
  - `normalizeDate(...)`：将日期字符串转换为标准格式。

