// データを前処理する関連機能
std::map<std::string, std::vector<std::string>> process_data(const std::string& filename) {
    std::map<std::string, std::vector<std::string>> data;

    // 重複行を削除する
    std::map<std::string, std::vector<std::string>> unique_data;
    unique_data = remove_duplicates(data);

    // 欠損値を補充する
    handle_missing_values(unique_data);

    return unique_data;
}

// メイン処理クラス
class DataProcessor {
private:
    std::queue<std::tuple<std::string, std::string, std::vector<std::string>>> result_queue;  // 結果キュー
    std::map<std::string, std::map<std::string, std::vector<std::string>>> results;        // 各タイプのデータ

public:
    DataProcessor() : result_queue(), results() {}

    ~DataProcessor() {
        // クリープの清理を実施する必要がある場合
        // 例: result_queueとresultsを完全に消去する
    }

    void process_file(const std::string& filename, const std::string& file_type) {
        // ファイルが存在することを確認する
        if (!std::filesystem::exists(filename)) {
            result_queue.push({"error", "File not found: " + filename});
            return;
        }

        // データを読み込む (例: CSV からデータを取得する)
        std::vector<std::map<std::string, std::vector<std::string>>> data_files;
        try {
            // ... (data loading code here)

            // 前処理を実施する
            auto processed_data = process_data(filename);

            // 各タイプに基づいてメトリックスを計算する
            if (file_type == "transaction") {
                std::map<std::string, double> metrics;
                metrics["total_revenue"] = calculate_total_revenue(processed_data);
                metrics["average_order_value"] = calculate_average_order_value(processed_data);
                // ほかメトリックスを加える
                results[file_type] = metrics;
            } else if (file_type == "chat") {
                std::map<std::string, double> sentiment_metrics;
                // テキストを前処理しキーワード抽出と感情分析を行う
                normalize_text(processed_data);
                extract_keywords(processed_data, sent_to_keyword_map);
                calculate_sentiment(sent_to_keyword_map, sentiment_metrics);
                results[file_type] = sentiment_metrics;
            } else if (file_type == "product") {
                std::map<std::string, int> metrics;
                metrics["view_count"] = count_product_views(processed_data);
                metrics["popular_products"] = get_top_popular_items(processed_data);
                // ほかメトリックスを加える
                results[file_type] = metrics;
            }

            result_queue.push({"results", processed_data});
        } catch (const std::exception& e) {
            result_queue.push({"error", "Error processing file: " + filename + " - " + e.what()});
        }
    }
};

int main() {
    // 槽設定を読み込む
    std::map<std::string, std::string> params = load_params("config.yml");

    // データベースマネージャーを初期化する
    DatabaseManager db_manager(params["db_connection"], params["report_dir"]);

    DataProcessor processor;

    // 対応のCSV ファイルをリストにする
    std::vector<std::string> files = list_files(params["data_dir"]);
    std::vector<std::thread> threads;

    for (const std::string& file : files) {
        if (!file_ends_with(file, ".csv")) continue;

        // ファイルタイプを指定する
        std::string file_type = params.get("file_type", "default");

        // メインプロセッサーをスタートする
        threads.emplace_back([this, file, file_type]() {
            processor.process_file(file, file_type);
        });
    }

    // プロセッサーを待機する
    for (auto& thread : threads) {
        thread.join();
    }

    // 結果を収集する
    while (!processor.result_queue.empty()) {
        auto item = processor.result_queue.front();
        processor.result_queue.pop();

        if (std::get<0>(item) == "results") {
            processor.results = std::get<1>(item);
        } else if (std::get<0>(item) == "error") {
            print_error(std::get<1>(item));
        }
    }

    // データをデータベースに保存する
    db_manager.save_to_database(processor.results);

    return 0;
}
```

