    string processed_date;
    string metric_type;
    double metric_value;
    string source_file;
    string cleaned_text;
    date timestamp;

    DatabaseRecord() : id(0) {}
};

void preprocess_data(const vector<string>& files, vector<DatabaseRecord>& results) {
    // Data cleaning and preprocessing logic
    for (const auto& file : files) {
        // Load data from file
        vector<pair<string, string>> lines;
        size_t pos = 0;
        ifstream fin(file, ios::binary | ios::in);
        if (!fin) {
            cout << "Error opening file: " << file << endl;
            continue;
        }
        while (getline(fin, tempstr, '\n')) {
            lines.push_back(make_pair(tempstr, file));
        }

        // Clean and preprocess data
        vector<DatabaseRecord> cleaned;
        for (const auto& entry : lines) {
            string text = entry.first;
            size_t pos = 0;

            // Deduplication based on some unique identifier
            size_t first_pos = text.find_first_not_of(" ", pos);
            while (first_pos != string::npos && text[first_pos] == ' ') first_pos++;
            if (pos != first_pos) {
                continue;
            }

            // Handle missing values and clean text
            vector<string> words;
            for (size_t i = 0; i < text.size(); ++i) {
                if (text[i] == ' ' || text[i] == '\t' || isspace(text[i])) {
                    if (!words.empty()) {
                        words.push_back(regular_expression_replace("([^\\s-]", "", text.substr(pos, i - pos)));
                        break;
                    }
                } else {
                    string word = regular_expression_replace("[^a-zA-Z0-9]", "", string(text.begin() + pos, text.begin() + i));
                    if (!word.empty()) {
                        words.push_back(word);
                    }
                }
            }

            // Store preprocessed data
            DatabaseRecord rec;
            rec.source_file = entry.second;
            rec.timestamp = system_clock::now().ptr();
            rec.cleaned_text = join(words, " ");
            cleaned.push_back(rec);
        }

        results.insert(results.end(), cleaned.begin(), cleaned.end());
    }
}

